  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400&display=swap" rel="stylesheet">

  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #FAFAFA;
      --bg-white: #FFFFFF;
      --text-primary: #171717;
      --text-secondary: #525252;
      --text-muted: #737373;
      --accent: #0072F5;
      --accent-hover: #005CC4;
      --border: #E5E5E5;
      --border-hover: #D4D4D4;
      --card-shadow: 0 1px 3px rgba(0,0,0,0.07), 0 1px 2px rgba(0,0,0,0.04);
      --card-shadow-hover: 0 8px 24px rgba(0,0,0,0.1), 0 2px 8px rgba(0,0,0,0.06);
      --radius: 12px;
      --radius-sm: 8px;
      --radius-pill: 100px;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    }

    html { font-family: var(--font); font-size: 16px; color: var(--text-primary); background: var(--bg); scroll-behavior: smooth; }
    body { min-height: 100vh; }
    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; border: none; background: none; font-family: var(--font); }

    /* ===== NAV ===== */
    .nav-wrap {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: rgba(250,250,250,0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
    }
    nav {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 60px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .nav-logo {
      font-size: 18px;
      font-weight: 800;
      letter-spacing: -0.5px;
      color: var(--text-primary);
      flex-shrink: 0;
      margin-right: 16px;
    }
    .nav-logo .accent { color: var(--accent); }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 2px;
      flex: 1;
    }
    .nav-item {
      position: relative;
    }
    .nav-link {
      display: flex;
      align-items: center;
      gap: 3px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 6px 10px;
      border-radius: 6px;
      transition: color 0.15s, background 0.15s;
      white-space: nowrap;
    }
    .nav-link:hover { color: var(--text-primary); background: rgba(0,0,0,0.04); }
    .nav-link svg { flex-shrink: 0; transition: transform 0.2s; }
    .nav-item:hover .nav-link svg { transform: rotate(180deg); }

    /* Mega menus */
    .dropdown {
      display: none;
      position: absolute;
      top: calc(100% + 6px);
      left: 0;
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: 0 12px 40px rgba(0,0,0,0.12), 0 4px 16px rgba(0,0,0,0.06);
      z-index: 200;
      padding: 12px;
      animation: fadeIn 0.15s ease;
    }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
    .nav-item:hover .dropdown,
    .nav-item.open .dropdown { display: block; }
    .dropdown-products { min-width: 600px; }
    .dropdown-resources { min-width: 420px; }

    .mega-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px;
    }
    .resources-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px;
    }
    .dropdown-col h4 {
      font-size: 10.5px;
      font-weight: 700;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      padding: 8px 10px 4px;
      margin-bottom: 2px;
    }
    .dropdown-item {
      display: block;
      padding: 8px 10px;
      border-radius: 6px;
      transition: background 0.12s;
    }
    .dropdown-item:hover { background: rgba(0,114,245,0.06); }
    .dropdown-item-name {
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-primary);
    }
    .dropdown-item-desc {
      font-size: 12px;
      color: var(--text-muted);
      margin-top: 1px;
      line-height: 1.4;
    }
    .dropdown-link {
      display: block;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 7px 10px;
      border-radius: 6px;
      transition: background 0.12s, color 0.12s;
    }
    .dropdown-link:hover { background: rgba(0,114,245,0.06); color: var(--accent); }

    /* Nav right */
    .nav-actions {
      display: flex;
      align-items: center;
      gap: 6px;
      margin-left: auto;
      flex-shrink: 0;
    }
    .btn-nav-ghost {
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 7px 14px;
      border-radius: 6px;
      transition: all 0.15s;
    }
    .btn-nav-ghost:hover { color: var(--text-primary); background: rgba(0,0,0,0.04); }
    .btn-nav-primary {
      font-size: 13.5px;
      font-weight: 600;
      color: #fff;
      background: var(--text-primary);
      padding: 7px 14px;
      border-radius: 6px;
      transition: all 0.15s;
    }
    .btn-nav-primary:hover { background: #333; }

    /* ===== MAIN ===== */
    main {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px 96px;
    }

    /* Blog hero */
    .blog-hero {
      padding: 72px 0 52px;
      border-bottom: 1px solid var(--border);
    }
    .blog-hero h1 {
      font-size: 52px;
      font-weight: 800;
      letter-spacing: -2px;
      line-height: 1.08;
      color: var(--text-primary);
    }
    .blog-hero p {
      font-size: 20px;
      color: var(--text-secondary);
      margin-top: 10px;
      font-weight: 400;
      line-height: 1.5;
    }

    /* ===== FILTER BAR ===== */
    .filter-bar {
      padding: 28px 0 32px;
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }
    .filter-pills {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      align-items: center;
      flex: 1;
    }
    .pill {
      font-family: var(--font);
      font-size: 13px;
      font-weight: 500;
      padding: 6px 14px;
      border-radius: var(--radius-pill);
      border: 1px solid var(--border);
      color: var(--text-secondary);
      background: var(--bg-white);
      transition: all 0.15s;
      cursor: pointer;
      line-height: 1;
    }
    .pill:hover { border-color: var(--accent); color: var(--accent); background: rgba(0,114,245,0.04); }
    .pill.active {
      background: var(--text-primary);
      color: #fff;
      border-color: var(--text-primary);
    }
    .pill.active:hover { background: #333; border-color: #333; color: #fff; }

    .search-wrap {
      position: relative;
      flex-shrink: 0;
    }
    .search-icon {
      position: absolute;
      left: 11px;
      top: 50%;
      transform: translateY(-50%);
      color: var(--text-muted);
      pointer-events: none;
      width: 16px;
      height: 16px;
    }
    .search-input {
      font-family: var(--font);
      font-size: 14px;
      padding: 8px 12px 8px 34px;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      background: var(--bg-white);
      color: var(--text-primary);
      width: 220px;
      outline: none;
      transition: all 0.15s;
    }
    .search-input::placeholder { color: var(--text-muted); }
    .search-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(0,114,245,0.12); }

    /* ===== FEATURED ===== */
    .featured-section { padding: 0 0 56px; }
    .section-eyebrow {
      font-size: 11px;
      font-weight: 700;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 20px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 3fr 2fr;
      grid-template-rows: 1fr 1fr;
      gap: 20px;
    }
    .featured-main {
      grid-row: span 2;
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 36px;
      transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      box-shadow: var(--card-shadow);
    }
    .featured-main:hover {
      box-shadow: var(--card-shadow-hover);
      transform: translateY(-3px);
      border-color: rgba(0,114,245,0.2);
    }
    .featured-side {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 28px;
      transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      box-shadow: var(--card-shadow);
    }
    .featured-side:hover {
      box-shadow: var(--card-shadow-hover);
      transform: translateY(-3px);
      border-color: rgba(0,114,245,0.2);
    }

    .card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 14px;
    }
    .cat-tag {
      font-size: 10.5px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--accent);
      background: rgba(0,114,245,0.09);
      padding: 3px 9px;
      border-radius: 4px;
    }
    .cat-tag.engineering { color: #7C3AED; background: rgba(124,58,237,0.09); }
    .cat-tag.customers { color: #059669; background: rgba(5,150,105,0.09); }
    .cat-tag.security { color: #DC2626; background: rgba(220,38,38,0.09); }
    .cat-tag.community { color: #D97706; background: rgba(217,119,6,0.09); }
    .cat-tag.company { color: #0891B2; background: rgba(8,145,178,0.09); }
    .cat-tag.changelog { color: #6D28D9; background: rgba(109,40,217,0.09); }
    .cat-tag.press { color: #BE185D; background: rgba(190,24,93,0.09); }

    .card-date {
      font-size: 13px;
      color: var(--text-muted);
    }

    .featured-main .card-title {
      font-size: 30px;
      font-weight: 800;
      letter-spacing: -0.8px;
      line-height: 1.2;
      margin-bottom: 14px;
      color: var(--text-primary);
    }
    .featured-side .card-title {
      font-size: 19px;
      font-weight: 700;
      letter-spacing: -0.3px;
      line-height: 1.3;
      margin-bottom: 10px;
      color: var(--text-primary);
    }
    .card-excerpt {
      font-size: 15px;
      line-height: 1.7;
      color: var(--text-secondary);
    }
    .featured-side .card-excerpt {
      font-size: 14px;
      line-height: 1.6;
      flex: 1;
    }

    /* Stats strip */
    .stats-strip {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1px;
      background: var(--border);
      border-radius: var(--radius-sm);
      border: 1px solid rgba(0,114,245,0.18);
      margin: 24px 0;
      overflow: hidden;
    }
    .stat-item {
      background: #EFF6FF;
      padding: 16px 12px;
      text-align: center;
    }
    .stat-number {
      font-size: 24px;
      font-weight: 800;
      color: var(--accent);
      letter-spacing: -0.5px;
      line-height: 1;
    }
    .stat-label {
      font-size: 11.5px;
      color: #3B82F6;
      margin-top: 4px;
      line-height: 1.4;
    }

    .card-author {
      display: flex;
      align-items: center;
      gap: 9px;
      margin-top: 20px;
      padding-top: 16px;
      border-top: 1px solid var(--border);
    }
    .featured-side .card-author { margin-top: 16px; padding-top: 12px; }
    .avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: #fff;
      flex-shrink: 0;
      letter-spacing: 0.02em;
    }
    .card-author-name {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
    }

    /* ===== LATEST NEWS ===== */
    .latest-section { padding: 0 0 56px; }
    .section-header {
      display: flex;
      align-items: baseline;
      gap: 12px;
      margin-bottom: 24px;
    }
    .section-header h2 {
      font-size: 26px;
      font-weight: 700;
      letter-spacing: -0.5px;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      min-height: 200px;
    }
    .post-card {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 24px;
      transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      box-shadow: var(--card-shadow);
    }
    .post-card:hover {
      box-shadow: var(--card-shadow-hover);
      transform: translateY(-2px);
      border-color: rgba(0,114,245,0.2);
    }
    .post-card.hidden { display: none; }
    .post-card .card-title {
      font-size: 16.5px;
      font-weight: 600;
      letter-spacing: -0.2px;
      line-height: 1.4;
      margin-bottom: 10px;
      flex: 1;
    }
    .post-card .card-excerpt {
      font-size: 14px;
      line-height: 1.65;
      color: var(--text-secondary);
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .post-card .card-author { margin-top: 14px; padding-top: 12px; }

    /* No results */
    .no-results {
      display: none;
      grid-column: 1 / -1;
      text-align: center;
      padding: 80px 24px;
    }
    .no-results-icon {
      width: 48px;
      height: 48px;
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
    }
    .no-results p {
      font-size: 16px;
      color: var(--text-muted);
      line-height: 1.5;
    }
    .no-results p strong { color: var(--text-secondary); }

    /* Show more */
    .show-more-wrap {
      text-align: center;
      margin-top: 32px;
    }
    .btn-show-more {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      background: var(--bg-white);
      border: 1px solid var(--border);
      padding: 12px 32px;
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: all 0.15s;
      box-shadow: var(--card-shadow);
    }
    .btn-show-more:hover { border-color: var(--accent); color: var(--accent); background: rgba(0,114,245,0.03); }
    .btn-show-more:active { transform: scale(0.98); }

    /* ===== CTA BANNER ===== */
    .cta-section {
      background: var(--text-primary);
      border-radius: 16px;
      padding: 64px 56px;
      margin-bottom: 64px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      align-items: center;
    }
    .cta-left {}
    .cta-eyebrow {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: rgba(255,255,255,0.4);
      margin-bottom: 12px;
    }
    .cta-left h2 {
      font-size: 34px;
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.8px;
      line-height: 1.2;
      margin-bottom: 28px;
    }
    .cta-left h2 .highlight { color: #60A5FA; }
    .cta-actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }
    .cta-btn-primary {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      background: #fff;
      padding: 11px 22px;
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }
    .cta-btn-primary:hover { background: #EFF6FF; }
    .cta-btn-secondary {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      color: rgba(255,255,255,0.75);
      background: transparent;
      border: 1px solid rgba(255,255,255,0.18);
      padding: 11px 22px;
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }
    .cta-btn-secondary:hover { background: rgba(255,255,255,0.07); color: #fff; border-color: rgba(255,255,255,0.3); }
    .cta-right {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: var(--radius);
      padding: 28px 32px;
      min-width: 300px;
      flex-shrink: 0;
    }
    .cta-right h3 {
      font-size: 17px;
      font-weight: 700;
      color: #fff;
      margin-bottom: 8px;
      letter-spacing: -0.2px;
    }
    .cta-right p {
      font-size: 13.5px;
      color: rgba(255,255,255,0.55);
      line-height: 1.6;
      margin-bottom: 20px;
    }
    .cta-enterprise-btn {
      display: inline-block;
      font-family: var(--font);
      font-size: 13.5px;
      font-weight: 600;
      color: #60A5FA;
      background: rgba(96,165,250,0.1);
      border: 1px solid rgba(96,165,250,0.25);
      padding: 9px 18px;
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }
    .cta-enterprise-btn:hover { background: rgba(96,165,250,0.18); border-color: rgba(96,165,250,0.4); }

    /* ===== FOOTER ===== */
    footer {
      background: var(--text-primary);
      padding: 64px 0 32px;
    }
    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px;
      margin-bottom: 56px;
    }
    .footer-col h4 {
      font-size: 12.5px;
      font-weight: 600;
      color: rgba(255,255,255,0.85);
      margin-bottom: 12px;
      letter-spacing: 0.01em;
    }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 7px; }
    .footer-col ul li a {
      font-size: 13px;
      color: rgba(255,255,255,0.45);
      transition: color 0.15s;
      line-height: 1.4;
    }
    .footer-col ul li a:hover { color: rgba(255,255,255,0.85); }
    .footer-divider {
      border: none;
      border-top: 1px solid rgba(255,255,255,0.08);
      margin-bottom: 28px;
    }
    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
    }
    .footer-logo {
      font-size: 17px;
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.5px;
    }
    .footer-logo .accent { color: var(--accent); }
    .footer-status {
      display: flex;
      align-items: center;
      gap: 7px;
      font-size: 13px;
