  // ===== STATE =====
  let activeCategory = 'all';
  let searchQuery = '';
  let showAll = false;
  const INITIAL_COUNT = 6;

  // ===== HELPERS =====
  function categoryTagClass(cat) {
    const map = {
      engineering: 'engineering',
      customers: 'customers',
      security: 'security',
      community: 'community',
      company: 'company',
      changelog: 'changelog',
      press: 'press',
      v0: '',
    };
    return map[cat] || '';
  }

  function getFilteredPosts() {
    return posts.filter(p => {
      const matchCat = activeCategory === 'all' || p.category === activeCategory;
      const q = searchQuery.toLowerCase();
      const matchSearch = !q ||
        p.title.toLowerCase().includes(q) ||
        p.excerpt.toLowerCase().includes(q) ||
        p.author.toLowerCase().includes(q) ||
        p.categoryLabel.toLowerCase().includes(q);
      return matchCat && matchSearch;
    });
  }

  function renderPosts() {
    const grid = document.getElementById('posts-grid');
    const noResults = document.getElementById('no-results');
    const showMoreWrap = document.getElementById('show-more-wrap');

    // Clear existing post cards (keep no-results)
    const existingCards = grid.querySelectorAll('.post-card');
    existingCards.forEach(c => c.remove());

    const filtered = getFilteredPosts();
    const visible = showAll ? filtered : filtered.slice(0, INITIAL_COUNT);

    if (filtered.length === 0) {
      noResults.style.display = 'block';
      showMoreWrap.style.display = 'none';
      return;
    }
    noResults.style.display = 'none';

    visible.forEach(post => {
      const card = document.createElement('article');
      card.className = 'post-card';
      card.setAttribute('tabindex', '0');
      card.setAttribute('role', 'article');
      const tagClass = categoryTagClass(post.category);
      card.innerHTML = `
        <div class="card-meta">
          <span class="cat-tag ${tagClass}">${post.categoryLabel}</span>
          <span class="card-date">${post.date}</span>
        </div>
        <h3 class="card-title">${post.title}</h3>
        <p class="card-excerpt">${post.excerpt}</p>
        <div class="card-author">
          <div class="avatar" style="background: ${post.avatarColor};">${post.initials}</div>
          <span class="card-author-name">${post.author}</span>
        </div>
      `;
      grid.appendChild(card);
    });

    // Show more button
    if (!showAll && filtered.length > INITIAL_COUNT) {
      showMoreWrap.style.display = 'block';
      document.getElementById('btn-show-more').textContent = `Show more posts (${filtered.length - visible.length} more)`;
    } else {
      showMoreWrap.style.display = 'none';
    }
  }

  // ===== INTERACTIONS =====

  // Category pills
  document.getElementById('filter-pills').addEventListener('click', e => {
    const pill = e.target.closest('.pill');
    if (!pill) return;
    document.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
    pill.classList.add('active');
    activeCategory = pill.dataset.category;
    showAll = false;
    renderPosts();
  });

  // Search
  const searchInput = document.getElementById('search-input');
  let searchDebounce;
  searchInput.addEventListener('input', e => {
    clearTimeout(searchDebounce);
    searchDebounce = setTimeout(() => {
      searchQuery = e.target.value.trim();
      showAll = false;
      renderPosts();
    }, 200);
  });

  // Show more
  document.getElementById('btn-show-more').addEventListener('click', () => {
    showAll = true;
    renderPosts();
  });

  // Nav dropdowns (click toggle for keyboard/mobile support)
  document.querySelectorAll('.nav-item').forEach(item => {
    item.addEventListener('click', e => {
      const isLink = e.target.closest('.dropdown-item, .dropdown-link, .btn-nav-ghost, .btn-nav-primary');
      if (isLink) return;
      const wasOpen = item.classList.contains('open');
      document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('open'));
      if (!wasOpen) item.classList.add('open');
      e.stopPropagation();
    });
  });
  document.addEventListener('click', () => {
    document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('open'));
  });

  // Close dropdowns on Escape
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('open'));
    }
  });

  // ===== INIT =====
  renderPosts();
</script>

